import test from 'node:test';
import assert from 'node:assert/strict';
import { createSearch } from '../src/search.js';

const empty = { draft: '', submitted: '', status: 'idle', items: [], error: null };

function deferredSearch() {
  const requests = [];
  const search = createSearch(query => new Promise((resolve, reject) => {
    requests.push({ query, resolve, reject });
  }));
  return { search, requests };
}

test('old failure cannot finish the new loading request for the same query after reset', async () => {
  const { search, requests } = deferredSearch();
  search.setDraft('same');
  const old = search.submit();
  search.reset();
  search.setDraft('same');
  const fresh = search.submit();

  assert.equal(requests.length, 2);
  assert.deepEqual(requests.map(request => request.query), ['same', 'same']);
  requests[0].reject(new Error('old failure'));
  await old;
  assert.deepEqual(search.getState(), {
    draft: 'same', submitted: 'same', status: 'loading', items: [], error: null,
  });

  requests[1].resolve([{ user_id: 'fresh', display_name: 'Fresh' }]);
  await fresh;
  assert.deepEqual(search.getState(), {
    draft: 'same', submitted: 'same', status: 'success',
    items: [{ id: 'fresh', label: 'Fresh' }], error: null,
  });
});

test('reset clears errors and retry ignores even an edited draft until a new submission', async () => {
  const { search, requests } = deferredSearch();
  search.setDraft('failed');
  const failed = search.submit();
  requests[0].reject(new Error('offline'));
  await failed;
  const previous = search.getState();
  assert.equal(previous.error, 'offline');

  assert.equal(search.reset(), undefined);
  assert.deepEqual(search.getState(), empty);
  search.reset();
  const snapshot = search.getState();
  snapshot.items.push({ id: 'injected', label: 'Injected' });
  assert.deepEqual(search.getState(), empty);

  search.setDraft('unsent');
  assert.equal(await search.retry(), undefined);
  assert.equal(requests.length, 1);
  assert.deepEqual(search.getState(), { ...empty, draft: 'unsent' });
  assert.deepEqual(previous, {
    draft: 'failed', submitted: 'failed', status: 'error', items: [], error: 'offline',
  });

  const fresh = search.submit();
  assert.equal(requests[1].query, 'unsent');
  requests[1].resolve([]);
  await fresh;
  assert.equal(search.getState().status, 'success');
});

