function createInitialState() {
  return { draft: '', submitted: '', status: 'idle', items: [], error: null };
}

export function createSearch(fetchUsers) {
  let state = createInitialState();
  let latestRequestId = 0;
  let disposed = false;

  async function runSearch(query) {
    if (disposed || !query) return;

    const requestId = ++latestRequestId;
    state = { ...state, submitted: query, status: 'loading', error: null };

    try {
      const users = await fetchUsers(query);
      if (disposed || requestId !== latestRequestId) return;

      state = {
        ...state,
        items: users.map(({ user_id, display_name }) => ({ id: user_id, label: display_name })),
        status: 'success',
      };
    } catch (error) {
      if (disposed || requestId !== latestRequestId) return;

      state = {
        ...state,
        error: error instanceof Error ? error.message : String(error),
        status: 'error',
      };
    }
  }

  return {
    setDraft(value) {
      if (!disposed) state = { ...state, draft: value };
    },
    submit() { return runSearch(state.draft.trim()); },
    retry() { return runSearch(state.submitted); },
    getState() { return structuredClone(state); },
    reset() {
      if (disposed) return;
      ++latestRequestId;
      state = createInitialState();
    },
    dispose() { disposed = true; },
  };
}

